mapper.select:
SELECT FROM xsy_pricing_time_price t LEFT JOIN xsy_product_sku k ON k.id = t.sku_id LEFT JOIN xsy_product_spu p ON p.id = k.spu_id WHERE t.deleted = FALSE AND t.sku_id = #{query.skuId}
AND t.start_at <= #{query.at} AND t.end_at > #{query.at}
AND (p.name LIKE CONCAT('%', #{query.keyword}, '%') OR k.sku_code LIKE CONCAT('%', #{query.keyword}, '%') OR k.spec_name LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY t.start_at DESC, t.id DESC

SELECT count(*) FROM xsy_pricing_time_price
WHERE deleted = FALSE
  AND sku_id = #{skuId}
  AND start_at < #{endAt} AND end_at > #{startAt}
  AND id <> #{excludeId}

mapper.update:
UPDATE xsy_pricing_time_price
SET deleted = TRUE, version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{id} AND version = #{version} AND deleted = FALSE
